<?php require_once __DIR__.'/includes/bootstrap.php';$redirect=return_url($_GET['redirect']??'dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('SELECT id,username,password,role FROM users WHERE username=? LIMIT 1');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify((string)($_POST['password']??''),$u['password'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['username'],'email'=>$u['username']];$_SESSION['user_id']=(int)$u['id'];$_SESSION['username']=$u['username'];$_SESSION['role']=$u['role'];header('Location: '.$redirect);exit;}$error='Invalid username or password.';}$pageTitle='Login';require __DIR__.'/includes/header.php';?><main><section class="section" style="max-width:520px;margin:auto"><article class="panel"><h1>Login / register</h1><?php if($error):?><div class="notice"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=csrf()?>"><input type="hidden" name="redirect" value="<?=h($redirect)?>"><label>Username</label><input name="username" required><label>Password</label><input name="password" type="password" required><button class="button" style="margin-top:18px">Login</button></form><p>New resident? <a href="register.php?redirect=<?=rawurlencode($redirect)?>" style="color:var(--teal)">Create an account</a></p></article></section></main><?php require __DIR__.'/includes/footer.php';?>
